/bin/bash -c "python - <<'PY'
import cv2, numpy as np
from PIL import Image
im=np.asarray(Image.open('first_frame.png').convert('RGB'))
variants={
 'gray':cv2.cvtColor(im,cv2.COLOR_RGB2GRAY),
 'R':im[:,:,0], 'G':im[:,:,1], 'B':im[:,:,2],
 'sat':cv2.cvtColor(im,cv2.COLOR_RGB2HSV)[:,:,1],
 'val':cv2.cvtColor(im,cv2.COLOR_RGB2HSV)[:,:,2],
}
for name,base in variants.items():
 for blur in [0,0.7,1.2]:
  g=base if not blur else cv2.GaussianBlur(base,(0,0),blur)
  for p1 in [40,60,90]:
   c=cv2.HoughCircles(g,cv2.HOUGH_GRADIENT,dp=1,minDist=7,param1=p1,param2=8,minRadius=3,maxRadius=8)
   if c is not None:
    arr=[]
    for x,y,r in c[0]:
     if 88<=x<=142 and 90<=y<=105: arr.append((round(float(x),1),round(float(y),1),round(float(r),1)))
    if arr: print(name,blur,p1,arr)
PY"
